create table if not exists public.employer_profiles (
  id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade,
  name text not null check (char_length(name) between 2 and 160), description text, website text, contact_email text,
  city text, country text, verification_status text not null default 'pending' check (verification_status in ('pending','verified','rejected')),
  is_sample boolean not null default false, created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now()), unique(owner_id, name)
);
create table if not exists public.job_listings (
  id uuid primary key default gen_random_uuid(), employer_id uuid not null references public.employer_profiles(id) on delete cascade,
  title text not null check (char_length(title) between 2 and 160), description text not null check (char_length(description) between 10 and 10000),
  job_type text not null check (job_type in ('full_time','part_time','contract','temporary','internship')), salary_min numeric(12,2), salary_max numeric(12,2), salary_currency text not null default 'GBP' check (salary_currency ~ '^[A-Z]{3}$'), location text, is_remote boolean not null default false,
  application_deadline timestamptz, sponsorship_status text not null default 'unknown' check (sponsorship_status in ('employer_declared','independently_checked','not_offered','unknown')), sponsorship_source text, sponsorship_checked_at timestamptz,
  status text not null default 'draft' check (status in ('draft','published','removed','expired')), is_sample boolean not null default false, created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now()), check (salary_min is null or salary_min >= 0), check (salary_max is null or salary_max >= salary_min)
);
create table if not exists public.cv_documents (
  id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, storage_path text not null unique, file_name text not null check (char_length(file_name) between 1 and 255), mime_type text not null check (mime_type in ('application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document')), size_bytes integer not null check (size_bytes between 1 and 10485760), created_at timestamptz not null default timezone('utc', now())
);
create table if not exists public.job_applications (
  id uuid primary key default gen_random_uuid(), job_id uuid not null references public.job_listings(id) on delete cascade, applicant_id uuid not null references auth.users(id) on delete cascade, cv_document_id uuid references public.cv_documents(id) on delete set null, cover_note text, status text not null default 'submitted' check (status in ('submitted','reviewing','shortlisted','rejected','withdrawn','hired')), created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now()), unique(job_id, applicant_id)
);
create table if not exists public.services (
  id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null check (char_length(name) between 2 and 160), category text not null, description text not null check (char_length(description) between 10 and 10000), pricing text, service_areas text[] not null default '{}', availability jsonb not null default '{}'::jsonb, images text[] not null default '{}', status text not null default 'draft' check (status in ('draft','published','removed','expired')), is_sample boolean not null default false, created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now())
);
create table if not exists public.service_requests (
  id uuid primary key default gen_random_uuid(), service_id uuid not null references public.services(id) on delete cascade, requester_id uuid not null references auth.users(id) on delete cascade, message text not null check (char_length(message) between 1 and 5000), requested_at timestamptz, status text not null default 'new' check (status in ('new','reviewing','accepted','declined','cancelled')), created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now())
);
create table if not exists public.events (
  id uuid primary key default gen_random_uuid(), organizer_id uuid not null references auth.users(id) on delete cascade, title text not null check (char_length(title) between 2 and 160), description text not null check (char_length(description) between 10 and 10000), venue_name text, venue_address text, online_url text, starts_at timestamptz not null, ends_at timestamptz not null, capacity integer check (capacity is null or capacity > 0), status text not null default 'draft' check (status in ('draft','published','removed','expired')), is_free boolean not null default true, is_sample boolean not null default false, created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now()), check (ends_at > starts_at), check (venue_name is not null or online_url is not null)
);
create table if not exists public.event_registrations (
  event_id uuid not null references public.events(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default timezone('utc', now()), primary key(event_id, user_id)
);
grant execute on function public.has_role(text) to anon;

create or replace function public.can_manage_employer(target uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.employer_profiles where id=target and owner_id=auth.uid()) or public.has_role('administrator'); $$;
create or replace function public.can_manage_service(target uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.services where id=target and owner_id=auth.uid()) or public.has_role('administrator'); $$;
create or replace function public.can_manage_event(target uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.events where id=target and organizer_id=auth.uid()) or public.has_role('administrator'); $$;
create or replace function public.expire_phase5_listings() returns trigger language plpgsql security definer set search_path = public as $$ begin update public.job_listings set status='expired' where status='published' and application_deadline is not null and application_deadline < timezone('utc',now()); update public.events set status='expired' where status='published' and ends_at < timezone('utc',now()); return null; end; $$;
create or replace function public.check_event_capacity() returns trigger language plpgsql security definer set search_path = public as $$ declare event_capacity integer; registered_count integer; begin select capacity into event_capacity from public.events where id=new.event_id for update; if event_capacity is not null then select count(*) into registered_count from public.event_registrations where event_id=new.event_id; if registered_count >= event_capacity then raise exception 'This event is full'; end if; end if; return new; end; $$;
drop trigger if exists event_capacity_guard on public.event_registrations;
create trigger event_capacity_guard before insert on public.event_registrations for each row execute procedure public.check_event_capacity();
create or replace function public.prevent_phase5_verification_change() returns trigger language plpgsql security definer set search_path = public as $$ begin if new.verification_status is distinct from old.verification_status and not (public.has_role('moderator') or public.has_role('administrator')) then raise exception 'Only moderators can change employer verification'; end if; return new; end; $$;
drop trigger if exists employer_verification_guard on public.employer_profiles;
create trigger employer_verification_guard before update on public.employer_profiles for each row execute procedure public.prevent_phase5_verification_change();

alter table public.employer_profiles enable row level security; alter table public.job_listings enable row level security; alter table public.cv_documents enable row level security; alter table public.job_applications enable row level security; alter table public.services enable row level security; alter table public.service_requests enable row level security; alter table public.events enable row level security; alter table public.event_registrations enable row level security;
create policy "Public employer profiles" on public.employer_profiles for select to anon, authenticated using (verification_status='verified' or owner_id=auth.uid() or public.has_role('moderator') or public.has_role('administrator'));
create policy "Owners create employers" on public.employer_profiles for insert to authenticated with check (owner_id=auth.uid());
create policy "Owners update employers" on public.employer_profiles for update to authenticated using (owner_id=auth.uid() or public.has_role('administrator')) with check (owner_id=auth.uid() or public.has_role('administrator'));
create policy "Public jobs" on public.job_listings for select to anon, authenticated using (status='published' and (application_deadline is null or application_deadline >= timezone('utc',now())) or public.can_manage_employer(employer_id) or public.has_role('moderator') or public.has_role('administrator'));
create policy "Employer owners create jobs" on public.job_listings for insert to authenticated with check (public.can_manage_employer(employer_id));
create policy "Employer owners update jobs" on public.job_listings for update to authenticated using (public.can_manage_employer(employer_id)) with check (public.can_manage_employer(employer_id));
create policy "Employer owners delete jobs" on public.job_listings for delete to authenticated using (public.can_manage_employer(employer_id));
create policy "Users manage own CVs" on public.cv_documents for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "Applicants and employers read applications" on public.job_applications for select to authenticated using (applicant_id=auth.uid() or exists(select 1 from public.job_listings j where j.id=job_id and public.can_manage_employer(j.employer_id)) or public.has_role('administrator'));
create policy "Users apply to active jobs" on public.job_applications for insert to authenticated with check (applicant_id=auth.uid() and exists(select 1 from public.job_listings j where j.id=job_id and j.status='published' and (j.application_deadline is null or j.application_deadline >= timezone('utc',now()))));
create policy "Applicants withdraw applications" on public.job_applications for update to authenticated using (applicant_id=auth.uid() or exists(select 1 from public.job_listings j where j.id=job_id and public.can_manage_employer(j.employer_id))) with check (applicant_id=auth.uid() or exists(select 1 from public.job_listings j where j.id=job_id and public.can_manage_employer(j.employer_id)));
create policy "Public services" on public.services for select to anon, authenticated using (status='published' or owner_id=auth.uid() or public.has_role('moderator') or public.has_role('administrator'));
create policy "Providers manage services" on public.services for all to authenticated using (owner_id=auth.uid() or public.has_role('administrator')) with check (owner_id=auth.uid() or public.has_role('administrator'));
create policy "Requesters and providers read requests" on public.service_requests for select to authenticated using (requester_id=auth.uid() or exists(select 1 from public.services s where s.id=service_id and public.can_manage_service(s.id)));
create policy "Users request services" on public.service_requests for insert to authenticated with check (requester_id=auth.uid() and exists(select 1 from public.services where id=service_id and status='published'));
create policy "Providers update requests" on public.service_requests for update to authenticated using (exists(select 1 from public.services s where s.id=service_id and public.can_manage_service(s.id)) or requester_id=auth.uid()) with check (exists(select 1 from public.services s where s.id=service_id and public.can_manage_service(s.id)) or requester_id=auth.uid());
create policy "Public events" on public.events for select to anon, authenticated using (status='published' or organizer_id=auth.uid() or public.has_role('moderator') or public.has_role('administrator'));
create policy "Organizers manage events" on public.events for all to authenticated using (organizer_id=auth.uid() or public.has_role('administrator')) with check (organizer_id=auth.uid() or public.has_role('administrator'));
create policy "Users read registrations" on public.event_registrations for select to authenticated using (user_id=auth.uid() or exists(select 1 from public.events e where e.id=event_id and public.can_manage_event(e.id)));
create policy "Users register once with capacity" on public.event_registrations for insert to authenticated with check (user_id=auth.uid() and exists(select 1 from public.events e where e.id=event_id and e.status='published' and (e.ends_at >= timezone('utc',now())) and (e.capacity is null or (select count(*) from public.event_registrations r where r.event_id=e.id) < e.capacity)));
create policy "Users cancel registrations" on public.event_registrations for delete to authenticated using (user_id=auth.uid() or exists(select 1 from public.events e where e.id=event_id and public.can_manage_event(e.id)));

insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('private-documents','private-documents',false,10485760,array['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document']) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=excluded.allowed_mime_types;
create policy "Users upload own CVs" on storage.objects for insert to authenticated with check (bucket_id='private-documents' and split_part(name,'/',1)=auth.uid()::text);
create policy "Users read own CVs" on storage.objects for select to authenticated using (bucket_id='private-documents' and (split_part(name,'/',1)=auth.uid()::text or exists(select 1 from public.job_applications a join public.job_listings j on j.id=a.job_id where a.cv_document_id::text=split_part(name,'/',2) and public.can_manage_employer(j.employer_id))));
create policy "Users delete own CVs" on storage.objects for delete to authenticated using (bucket_id='private-documents' and split_part(name,'/',1)=auth.uid()::text);
create index if not exists jobs_search_idx on public.job_listings(status, sponsorship_status, job_type, application_deadline, created_at desc); create index if not exists jobs_title_trgm_idx on public.job_listings using gin(title gin_trgm_ops); create index if not exists services_search_idx on public.services(status,category,created_at desc); create index if not exists events_search_idx on public.events(status,starts_at); create index if not exists applications_job_idx on public.job_applications(job_id,status,created_at desc); create index if not exists registrations_event_idx on public.event_registrations(event_id,created_at);
